// ---------------------------------------------------------------------------------------------------------------
// ColourConvertXBoxToPS2, SimpleDraw and Draw (0x00075c40..0x00076810), ported from the listing. The x87 code keeps
// the original's order and roundings.
// ---------------------------------------------------------------------------------------------------------------

#define DrawModelMatrix (*(MATRIX4 **)0x001e92d8)
#define DrawZ FLOAT_AT(0x001c3e28)

namespace {

// A batch's vertices (the statics of a batched draw, the name is ours). The colours are a function-local static
// array constructed on first use: their guard's bit 0 says they have been.
struct VertexBatch {
    Coord4 texCoords[128];              // +0x0000
    Coord4 positions[128];              // +0x0800
    int32_t count;                      // +0x1000
    uint32_t unknown1004[3];
    EAGL::TAR *texture;                 // +0x1010 the one every vertex in the batch has
    uint32_t unknown1014[3];
    PackedColour colours[128];          // +0x1020
    uint32_t coloursGuard;              // +0x1220
};
static_assert(offsetof(VertexBatch, count) == 0x1000 && offsetof(VertexBatch, texture) == 0x1010 &&
              offsetof(VertexBatch, colours) == 0x1020 && offsetof(VertexBatch, coloursGuard) == 0x1220,
              "VertexBatch layout");

#define QuadBatch (*(VertexBatch *)0x001e9420)       // DrawBatchedTexturedQuad's
#define SpriteBatch (*(VertexBatch *)0x001ea650)     // DrawBatchedSprite's

// A batch is drawn once it holds more than this many vertices
constexpr int32_t kBatchLimit = 120;

constexpr uint32_t kAlphaBlendingOn = 1;  // GeoPrimState::SetTransparencyMethod's

constexpr float kByteToUnit = 1.0f / 255.0f;
constexpr float kLumaGain = 1.0811f;
static_assert(std::bit_cast<uint32_t>(kByteToUnit) == 0x3b808081, "1/255");
static_assert(std::bit_cast<uint32_t>(kLumaGain) == 0x3f8a617c, "1.0811");

void ConstructColours(VertexBatch &batch) {
    if (!(batch.coloursGuard & 1)) {
        batch.coloursGuard |= 1;
        for (int i = 0; i < 128; i++)
            batch.colours[i].Construct();
    }
}

// Draws the batch's vertices as triangles with its texture
void DrawBatch(VertexBatch &batch) {
    TexturedRequests[TexturedRequestIndex]->positions.SetData(batch.positions);
    TexturedRequests[TexturedRequestIndex]->colours.SetData(batch.colours);
    TexturedRequests[TexturedRequestIndex]->texCoords.SetData(batch.texCoords);
    TexturedRequests[TexturedRequestIndex]->texture.SetData(batch.texture);
    SimpleTexturedMaterial->Draw(kTriangleList, batch.count, NULL);
}

// The batch drawn and restarted for `texture` when it changes or the batch is full
void StartBatch(VertexBatch &batch, EAGL::TAR *texture) {
    if (texture != batch.texture || batch.count > kBatchLimit) {
        if (batch.texture != NULL)
            DrawBatch(batch);
        batch.count = 0;
        batch.texture = texture;
    }
}

void AddBatchVertex(VertexBatch &batch, int index, const Coord4 *position, const Coord4 *texCoord, uint32_t colour) {
    batch.positions[index] = *position;
    batch.texCoords[index] = *texCoord;
    batch.colours[index].value = colour;
}

// A screen rectangle's corners as a strip: top left, top right, bottom left, bottom right
void RectangleCorners(Vec4 *corners, float x, float y, float width, float height) {
    float right = x + width;
    float bottom = y + height;
    corners[0] = {x, y, DrawZ, 1.0f};
    corners[1] = {right, y, DrawZ, 1.0f};
    corners[2] = {x, bottom, DrawZ, 1.0f};
    corners[3] = {right, bottom, DrawZ, 1.0f};
}

}  // namespace

// FUNC_AT(0x00075c40)
uint32_t ColourConvertXBoxToPS2(uint32_t colour) {
    double r = (int32_t)((colour >> 16) & 0xff) * (double)kByteToUnit;
    double g = (int32_t)((colour >> 8) & 0xff) * (double)kByteToUnit;
    double b = (int32_t)(colour & 0xff) * (double)kByteToUnit;

    float i = (float)(r * 0.596 - g * 0.275 - b * 0.321);
    float q = (float)(r * 0.212 - g * 0.523 + b * 0.311);
    double y = (g * 0.587 + r * 0.299) + b * 0.114;
    y = y * kLumaGain - 0.075;
    if (y > 1.0)
        y = 1.0;
    if (y < 0.0)
        y = 0.0;

    double i2 = i * 1.115;
    double q2 = q * 1.115;
    float red = (float)((i2 * 0.956 + q2 * 0.621) + y);
    float green = (float)(y - i2 * 0.272 - q2 * 0.647);
    float blue = (float)((y - i2 * 1.105) + q2 * 1.702);

    // Green is kept as a float between the clamp and the scale, red and blue as doubles
    double redClamped = red > 1.0f ? 1.0 : red;
    if (redClamped < 0.0)
        redClamped = 0.0;
    float greenClamped = green > 1.0f ? 1.0f : green;
    if (greenClamped < 0.0f)
        greenClamped = 0.0f;
    double blueClamped = blue > 1.0f ? 1.0 : blue;
    if (blueClamped < 0.0)
        blueClamped = 0.0;

    uint32_t red8 = RoundToInt((float)(redClamped * 255.0f));
    uint32_t green8 = RoundToInt((float)(greenClamped * 255.0));
    uint32_t blue8 = RoundToInt((float)(blueClamped * 255.0f));
    return (((red8 << 8) | green8) << 8) | (colour & 0xff000000) | blue8;
}

