// FUNC_AT(0x00075f60)
void Draw::DrawSprite(float x, float y, float width, float height, uint32_t colour, const SpriteTexCoords *texCoords, EAGL::TAR *texture) {
    uint32_t colours[4] = {colour, colour, colour, colour};
    Vec4 positions[4];
    RectangleCorners(positions, x, y, width, height);
    const Coord4 &topLeft = texCoords->topLeft;
    const Coord4 &bottomRight = texCoords->bottomRight;
    Vec4 uvs[4] = {
        {topLeft.x, topLeft.y, 1.0f, 1.0f},
        {bottomRight.x, topLeft.y, 1.0f, 1.0f},
        {topLeft.x, bottomRight.y, 1.0f, 1.0f},
        {bottomRight.x, bottomRight.y, 1.0f, 1.0f},
    };
    TexturedRequests[TexturedRequestIndex]->positions.SetData(positions);
    TexturedRequests[TexturedRequestIndex]->colours.SetData(colours);
    TexturedRequests[TexturedRequestIndex]->texCoords.SetData(uvs);
    TexturedRequests[TexturedRequestIndex]->texture.SetData(texture);
    SimpleTexturedMaterial->Draw(kTriangleStrip, 4, DrawModelMatrix);
}

