// FUNC_AT(0x00076330)
void Draw::DrawBatchedTexturedQuad(const Coord4 *p0, const Coord4 *p1, const Coord4 *p2, const Coord4 *p3,
                                   uint32_t colour, const Coord4 *texCoords, EAGL::TAR *texture) {
    VertexBatch &batch = QuadBatch;
    ConstructColours(batch);
    StartBatch(batch, texture);
    if (texture == NULL)
        return;
    int n = batch.count;
    AddBatchVertex(batch, n, p0, &texCoords[0], colour);
    AddBatchVertex(batch, n + 1, p1, &texCoords[1], colour);
    AddBatchVertex(batch, n + 2, p2, &texCoords[2], colour);
    AddBatchVertex(batch, n + 3, p1, &texCoords[1], colour);
    AddBatchVertex(batch, n + 4, p2, &texCoords[2], colour);
    AddBatchVertex(batch, n + 5, p3, &texCoords[3], colour);
    batch.count = n + 6;
}

// Only the texture coordinates' u and v are written.
// FUNC_AT(0x000765e0)
void Draw::DrawBatchedSprite(float x, float y, float width, float height, uint32_t colour,
                             const SpriteTexCoords *texCoords, EAGL::TAR *texture) {
    VertexBatch &batch = SpriteBatch;
    ConstructColours(batch);
    StartBatch(batch, texture);
    if (texture == NULL)
        return;
    Vec4 corners[4];
    RectangleCorners(corners, x, y, width, height);
    const Coord4 &topLeft = texCoords->topLeft;
    const Coord4 &bottomRight = texCoords->bottomRight;
    const float us[4] = {topLeft.x, bottomRight.x, topLeft.x, bottomRight.x};
    const float vs[4] = {topLeft.y, topLeft.y, bottomRight.y, bottomRight.y};
    int n = batch.count;
    for (int i = 0; i < 4; i++) {
        batch.positions[n + i] = corners[i];
        batch.texCoords[n + i].x = us[i];
        batch.texCoords[n + i].y = vs[i];
        batch.colours[n + i].value = colour;
    }
    batch.count = n + 4;
}
